audit_script:
$ErrorActionPreference = 'Stop'
try {
    $role = (Get-CimInstance Win32_ComputerSystem).DomainRole
    if ($role -ne 4 -and $role -ne 5) {
        Write-Output '** SKIP **'
        exit 0
    }
    $exportPath = Join-Path $env:TEMP ('secpol_{0}_{1}.cfg' -f $PID, (Get-Random))
    secedit /export /cfg $exportPath /areas USER_RIGHTS | Out-Null
    $content = Get-Content $exportPath -Raw
    if ($content -match '(?m)^\s*SeNetworkLogonRight\s*=\s*(.+?)\s*$') {
        $current = $Matches[1].Trim()
        $currentSids = $current -split ',' | ForEach-Object { $_.Trim().TrimStart('*') } | Where-Object { $_ } | Sort-Object
        $expected = @('S-1-5-9','S-1-5-11','S-1-5-32-544') | Sort-Object
        $diff = @(Compare-Object -ReferenceObject $expected -DifferenceObject $currentSids -SyncWindow 0)
        if ($diff.Count -eq 0) {
            Write-Output '** PASS **'
        } else {
            Write-Output '** FAIL **'
            Write-Output ('Current: ' + ($current -join ','))
        }
    } else {
        Write-Output '** ERROR **'
        Write-Output 'SeNetworkLogonRight not found in security policy export'
    }
    Remove-Item $exportPath -Force -ErrorAction SilentlyContinue
    exit 0
} catch {
    Write-Output '** ERROR **'
    Write-Output $_.Exception.Message
    exit 1
}

